function renderProfile(){['profileName','helloName','drawerName'].forEach(id=>$('#'+id).textContent=data.name);$('#profileBeastId').textContent=data.beastId;$('#drawerId').textContent=data.beastId;$('#profilePhone').textContent=data.phone;$('#profileInternational').textContent=international(data.phone);$('#profileId').textContent=data.id;$('#profileBalance').textContent=money(data.balance);$('#homeBalance').textContent=money(data.balance)}
function international(p){let d=(p||'').replace(/\D/g,'');if(d.startsWith('254'))return '+'+d;if(d.startsWith('0'))return '+254'+d.slice(1);return p||'—'}
function renderHistory(){const list=$('#historyList');list.innerHTML='';data.transactions.forEach(t=>{const e=document.createElement('div');e.className='item';const sign=t.sign||'-';e.innerHTML='<span style="font-size:22px">'+(sign==='+'?'↙':'↗')+'</span><div class="grow"><b></b><small></small><small></small><small></small><small></small></div><div class="amount"></div>';e.querySelector('.grow b').textContent=t.type;e.querySelectorAll('small')[0].textContent=t.detail;e.querySelectorAll('small')[1].textContent='Recipient: '+(t.recipient||'—')+' · Source: '+(t.source||'BEAST Wallet');e.querySelectorAll('small')[2].textContent='Reference: '+(t.ref||'BST-DEMO');e.querySelectorAll('small')[3].textContent=(t.date||new Date().toLocaleString())+' · BEAST fee: '+money(t.fee||0)+' · Provider: '+money(t.provider||0);const a=e.querySelector('.amount');a.textContent=(sign==='+'?'+':'−')+' '+money(t.amount);a.className='amount '+(sign==='+'?'positive':'negative');list.append(e)})}
