function addTx(type,amount,sign,detail,source,recipient,fee=0,provider=0){const ref='BST-'+Math.floor(10000000+Math.random()*89999999)+'-'+Math.floor(100+Math.random()*899);data.transactions.unshift({type,amount:Number(amount),sign,detail,source,recipient,ref,date:new Date().toLocaleString('en-GB'),fee,provider});if(data.transactions.length>100)data.transactions.length=100;save();renderProfile();notify(type+' '+(sign==='+'?'received':'recorded')+' in demo');}
function setFee(input,amount,fee,total){const n=Math.max(0,Number($(input).value)||0),f=n?Math.min(50,Math.max(0,Math.ceil(n/1000)*7)):0;$(amount).textContent=money(n);$(fee).textContent=money(f);if(total)$(total).textContent=money(n+f);return {n,f,total:n+f}}
function validPhone(v){return /^(?:0[17]\d{8}|\+254[17]\d{8}|254[17]\d{8}|BEAST-\d{1,12}|[A-Za-z0-9-]{5,30})$/i.test(v.trim())}
function sourceBalance(name){const s=data.sources.find(x=>x.name.toLowerCase()===name.toLowerCase());return s?Number(s.balance)||0:0}
function deductSource(name,amount){const s=data.sources.find(x=>x.name.toLowerCase()===name.toLowerCase());if(name==='BEAST Wallet'){if(data.balance<amount)return false;data.balance-=amount;if(s)s.balance=data.balance;return true}if(s){if(s.balance<amount)return false;s.balance-=amount;return true}return false}
function verifyPin(v){return String(v||'')===String(data.pin)}
