// Settings
$('#saveReceiveMethod').onclick=()=>{const name=$('#receiveMethod').value,dest=$('#receiveDestination').value.trim();if(name!=='BEAST Wallet'&&!dest)return toast('Enter the destination for this receiving method.');let r=data.receiving.find(x=>x.name===name);if(!r){r={name,destination:dest,on:true};data.receiving.push(r)}else{r.destination=name==='BEAST Wallet'?data.beastId:dest;r.on=true}save();renderSettings();toast('Receiving method saved in this browser.')};$('#saveSource').onclick=()=>{const name=$('#sourceType').value,number=$('#sourceNumber').value.trim(),balance=Number($('#sourceBalance').value)||0;let s=data.sources.find(x=>x.name===name);if(s){s.number=number;s.balance=balance}else data.sources.push({name,number,balance});if(name==='BEAST Wallet')data.balance=balance;save();renderSettings();renderProfile();toast('Demo payment source saved.')};$('#changePin').onclick=()=>{if($('#currentPin').value!==data.pin)return toast('Current PIN is incorrect.');if(!/^\d{4,6}$/.test($('#newPin').value)||$('#newPin').value!==$('#confirmPin').value)return toast('New PIN must be 4–6 digits and match confirmation.');data.pin=$('#newPin').value;save();['currentPin','newPin','confirmPin'].forEach(id=>$('#'+id).value='');toast('Demo PIN changed locally. Production must use backend-secured hashing.')};$('#changePassword').onclick=()=>{if($('#currentPassword').value!==data.password)return toast('Current password is incorrect.');if($('#newPassword').value.length<6||$('#newPassword').value!==$('#confirmPassword').value)return toast('New password must be at least 6 characters and match.');data.password=$('#newPassword').value;save();['currentPassword','newPassword','confirmPassword'].forEach(id=>$('#'+id).value='');toast('Demo password changed locally. Production must use backend-secured hashing.')};$('#darkMode').onclick=()=>{document.documentElement.style.setProperty('--bg','#050907');document.documentElement.style.setProperty('--panel','#0b1512');toast('Dark mode enabled.')};$('#lightMode').onclick=()=>{document.documentElement.style.setProperty('--bg','#e9f3ee');document.documentElement.style.setProperty('--panel','#ffffff');document.documentElement.style.setProperty('--panel2','#f4faf6');document.documentElement.style.setProperty('--text','#10231a');document.documentElement.style.setProperty('--muted','#536c60');$$('.card').forEach(c=>c.style.color='#10231a');toast('Light preview enabled. Reload restores the dark theme.')};$('#alertsToggle').onchange=()=>toast('Transaction alerts '+($('#alertsToggle').checked?'enabled':'disabled')+' in this preview.');$('#visibilityToggle').onchange=()=>toast('Screen visibility preview updated.');$('#bioBtn').onclick=()=>toast('Biometric authentication is a future integration placeholder.');$('#resetDemo').onclick=()=>{if(confirm('Reset all local BEAST demo data?')){localStorage.removeItem('beastMoneyDemo');data=defaultData();save();renderProfile();renderSettings();renderHistory();toast('Demo data reset.');showEntry('register')}};

const MARKET_TYPES=[
{name:'BEAST Marketplace',price:500,desc:'Sell physical products and promote listings.'},
{name:'BEAST Academy',price:300,desc:'Publish courses and learning content.'},
{name:'BEAST Business Hub',price:300,desc:'Business profile, customer enquiries and tools.'},
{name:'BEAST Ads & Promotions',price:1000,desc:'Create paid promotional campaigns.'},
{name:'BEAST Digital Services',price:500,desc:'Offer freelance and professional services.'},
{name:'BEAST AI Premium',price:499,desc:'Premium AI tools; working AI services require backend integration.'},
{name:'BEAST Digital Shop',price:300,desc:'Sell downloadable digital products.'},
{name:'BEAST Travel & Booking',price:500,desc:'List travel, accommodation and booking services.'},
{name:'BEAST Food & Delivery',price:500,desc:'List food, groceries and local delivery items.'},
{name:'BEAST Jobs & Opportunities',price:500,desc:'Post jobs and professional opportunities.'},
{name:'BEAST Airtime & Payments',price:500,desc:'Payment-service listing; provider agreements required.'},
{name:'BEAST Premium Membership',price:199,desc:'Premium membership tools and benefits.'}
];
let marketData={businesses:[],products:[]};
function marketLoad(){try{const x=JSON.parse(localStorage.getItem('beastMarketDemo')||'{}');marketData={businesses:Array.isArray(x.businesses)?x.businesses:[],products:Array.isArray(x.products)?x.products:[]}}catch(e){}}
function marketSave(){try{localStorage.setItem('beastMarketDemo',JSON.stringify(marketData))}catch(e){}}
function marketEsc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function marketDate(v){return new Date(v).toLocaleDateString('en-KE',{day:'numeric',month:'short',year:'numeric'})}
function marketRenderTypes(){const sel=$('#marketType');sel.innerHTML='';MARKET_TYPES.forEach((t,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=t.name+' — KSh '+t.price+'/month';sel.append(o)});marketUpdatePlan()}
function marketUpdatePlan(){const t=MARKET_TYPES[Number($('#marketType').value)||0];$('#marketPlanInfo').textContent='7 days free. After the trial: KSh '+t.price+'/month for '+t.name+'. This prototype will not charge you automatically.'}
function marketRenderBusinesses(){const box=$('#marketBusinesses');box.innerHTML='';if(!marketData.businesses.length){box.innerHTML='<div class="notice">No business registered on this device yet.</div>';return}marketData.businesses.forEach(b=>{const elapsed=Math.max(0,Math.floor((Date.now()-b.startedAt)/86400000));const days=Math.max(0,7-elapsed);const expired=days===0;const row=document.createElement('div');row.className='item market-business-row';const grow=document.createElement('div');grow.className='grow';const title=document.createElement('b');title.textContent=b.name;const desc=document.createElement('small');desc.textContent=b.type+' · Owner: '+b.owner+' · '+b.phone;const status=document.createElement('small');status.textContent=expired?'Trial ended · subscription not charged':'Free trial: '+days+' day(s) remaining';const price=document.createElement('small');price.textContent='KSh '+b.price+'/month · Started '+marketDate(b.startedAt);grow.append(title,desc,status,price);const badge=document.createElement('span');badge.className='pill';badge.textContent=expired?'TRIAL ENDED':'FREE TRIAL';row.append(grow,badge);box.append(row)})}
function marketRenderProducts(){const box=$('#marketProducts');box.innerHTML='';const q=($('#marketSearch').value||'').trim().toLowerCase();const rows=marketData.products.filter(p=>(p.name+' '+p.business+' '+p.type).toLowerCase().includes(q));$('#marketEmpty').classList.toggle('hide',rows.length>0);rows.forEach(p=>{const card=document.createElement('article');card.className='card market-product';if(p.image&&/^https?:\/\//i.test(p.image)){const img=document.createElement('img');img.src=p.image;img.alt=p.name;img.loading='lazy';img.onerror=()=>img.remove();card.append(img)}const body=document.createElement('div');body.className='productbody';const title=document.createElement('strong');title.textContent=p.name;const badge=document.createElement('span');badge.className='market-badge';badge.textContent=p.type;const price=document.createElement('div');price.className='market-price';price.textContent=money(p.price);const shop=document.createElement('small');shop.style.color='var(--muted)';shop.textContent=p.business+' · Stock: '+p.stock;const buy=document.createElement('button');buy.className='btn secondary';buy.textContent='Demo order';buy.onclick=()=>{if(p.stock<=0){toast('This product is out of stock.');return}const ok=confirm('Demo order for '+p.name+' at '+money(p.price)+'? No real payment will be taken.');if(!ok)return;p.stock--;marketSave();marketRenderProducts();$('#marketOrderMessage').innerHTML='<div class="notice ok">Demo order recorded for '+marketEsc(p.name)+'. No payment or delivery was made.</div>';};body.append(title,badge,price,shop,buy);card.append(body);box.append(card)})}
function marketTab(t){$$('[data-markettab]').forEach(b=>b.classList.toggle('active',b.dataset.markettab===t));$$('.market-panel').forEach(p=>p.classList.toggle('hide',p.id!=='market-'+t));if(t==='shop')marketRenderProducts()}
$$('[data-markettab]').forEach(b=>b.addEventListener('click',()=>marketTab(b.dataset.markettab)));
$('#marketType').addEventListener('change',marketUpdatePlan);$('#marketSearch').addEventListener('input',marketRenderProducts);
$('#marketRegister').onclick=()=>{const type=MARKET_TYPES[Number($('#marketType').value)||0],name=$('#marketBusinessName').value.trim(),owner=$('#marketOwnerName').value.trim(),phone=$('#marketPhone').value.trim(),description=$('#marketDescription').value.trim(),product=$('#marketProductName').value.trim(),price=Number($('#marketProductPrice').value),stock=Number($('#marketProductStock').value);if(!name||!owner||!phone)return toast('Enter business name, owner name and phone number.');if(!$('#marketTerms').checked)return toast('Please confirm the demo trial terms.');if(product&&(!Number.isFinite(price)||price<=0||!Number.isInteger(stock)||stock<0))return toast('Enter a valid product price and stock quantity.');const id='BM-'+Date.now().toString(36).toUpperCase();const business={id,type:type.name,price:type.price,name,owner,phone,description,startedAt:Date.now()};marketData.businesses.unshift(business);if(product)marketData.products.unshift({id:'MP-'+Date.now().toString(36).toUpperCase(),businessId:id,business:name,type:type.name,name:product,price,stock,image:$('#marketProductImage').value.trim()});marketSave();marketRenderBusinesses();marketRenderProducts();$('#marketMessage').innerHTML='<div class="notice ok">Business registered in this browser. Your 7-day demo trial has started. '+(product?'Your product is now listed in Shop.':'You can add a product by registering another business with product details.')+' No real billing is enabled.</div>';['marketBusinessName','marketOwnerName','marketPhone','marketDescription','marketProductName','marketProductPrice','marketProductImage'].forEach(id=>$('#'+id).value='');$('#marketProductStock').value='1';$('#marketTerms').checked=false;toast('Business registered with a 7-day local demo trial.')};
marketLoad();marketRenderTypes();marketRenderBusinesses();marketRenderProducts();

const BIZ_TYPES=[
{name:'BEAST Marketplace',price:500,desc:'Sell physical products and promote listings.'},
{name:'BEAST Academy',price:300,desc:'Publish courses and learning content.'},
{name:'BEAST Business Hub',price:300,desc:'Business profile, customer enquiries and business tools.'},
{name:'BEAST Ads & Promotions',price:1000,desc:'Plan promotional campaigns and advertising.'},
{name:'BEAST Digital Services',price:500,desc:'Offer freelance and professional services.'},
{name:'BEAST AI Premium',price:499,desc:'Premium AI features; live AI requires backend integration.'},
{name:'BEAST Digital Shop',price:300,desc:'Sell downloads, templates and digital products.'},
{name:'BEAST Travel & Booking',price:500,desc:'Promote travel, accommodation and booking services.'},
{name:'BEAST Food & Delivery',price:500,desc:'Promote food, groceries and local delivery.'},
{name:'BEAST Jobs & Opportunities',price:500,desc:'Publish job posts and professional opportunities.'},
{name:'BEAST Airtime & Payments',price:500,desc:'Payment-related listings; provider agreements are required.'},
{name:'BEAST Premium Membership',price:199,desc:'Premium membership tools and benefits.'}
];
let bizData={businesses:[]}, bizSelected=0, bizCurrentTab='dashboard';
function bizLoad(){try{const d=JSON.parse(localStorage.getItem('beastBusinessDashboard')||'{}');bizData={businesses:Array.isArray(d.businesses)?d.businesses:[]}}catch(e){bizData={businesses:[]}}}
function bizSave(){try{localStorage.setItem('beastBusinessDashboard',JSON.stringify(bizData))}catch(e){toast('Could not save business data on this device.')}}
function bizEscape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function bizSetTab(name){bizCurrentTab=name;$$('[data-biz-tab]').forEach(b=>b.classList.toggle('active',b.dataset.bizTab===name));$$('.biz-panel').forEach(p=>p.classList.toggle('hide',p.id!=='biz-'+name));if(name==='dashboard')bizRenderRegistered();if(name==='shop')bizRenderShop()}
function bizChoose(i){bizSelected=i;$('#bizType').value=String(i);bizUpdatePlan();bizSetTab('register')}
function bizRenderTypes(){
 const sel=$('#bizType');sel.innerHTML='';
 BIZ_TYPES.forEach((t,i)=>{const opt=document.createElement('option');opt.value=String(i);opt.textContent=t.name+' — KSh '+t.price+'/month';sel.append(opt)});
 $('#bizTypeCards').innerHTML=BIZ_TYPES.map((t,i)=>`<button type="button" class="card biz-service" data-biz-choose="${i}"><span class="icon">${['🏪','🎓','🏢','📢','🧰','🤖','🛍️','✈️','🍲','💼','📲','👑'][i]}</span><b>${bizEscape(t.name)}</b><small>${bizEscape(t.desc)}</small><span class="price">KSh ${t.price}/month</span><span class="trial">7-day free trial</span><span class="link">Register →</span></button>`).join('');
 $$('[data-biz-choose]').forEach(b=>b.addEventListener('click',()=>bizChoose(Number(b.dataset.bizChoose))));
}
function bizUpdatePlan(){const t=BIZ_TYPES[Number($('#bizType').value)||0];bizSelected=Number($('#bizType').value)||0;$('#bizPlanInfo').textContent='7 days free, then KSh '+t.price+'/month. No automatic payment is possible in this prototype.';$('#bizPlanDescription').textContent=t.desc;$('#bizRegisterHeading').textContent='Start your 7-day free trial';}
function bizRenderRegistered(){
 const box=$('#bizRegisteredList');if(!bizData.businesses.length){box.innerHTML='<div class="notice">No businesses registered here yet. Choose one of the 12 services above to start.</div>';return}
 box.innerHTML=bizData.businesses.map(b=>{const elapsed=Math.max(0,Math.floor((Date.now()-b.startedAt)/86400000));const days=Math.max(0,7-elapsed);const ended=days===0;return `<div class="biz-list-row"><div><b>${bizEscape(b.name)}</b><small>${bizEscape(b.type)} · Owner: ${bizEscape(b.owner)} · ${bizEscape(b.phone)}</small><small>${ended?'7-day trial ended — subscription required to continue':'Free trial: '+days+' day(s) remaining'}</small><small>KSh ${b.price}/month · Started ${new Date(b.startedAt).toLocaleDateString('en-KE')}</small></div><span class="biz-status">${ended?'TRIAL ENDED':'FREE TRIAL'}</span></div>`}).join('');
}
function bizRenderShop(){
 const box=$('#bizShopProducts'),q=($('#bizShopSearch').value||'').trim().toLowerCase();
 const products=(typeof marketData!=='undefined'&&Array.isArray(marketData.products))?marketData.products.filter(p=>(p.name+' '+p.business+' '+p.type).toLowerCase().includes(q)):[];
 box.innerHTML=products.map(p=>`<article class="card"><b>${bizEscape(p.name)}</b><small>${bizEscape(p.business)} · ${bizEscape(p.type)}</small><strong style="color:var(--gold)">KSh ${Number(p.price||0).toLocaleString('en-KE')}</strong><small>Stock: ${Number(p.stock||0)}</small></article>`).join('');
 $('#bizShopEmpty').classList.toggle('hide',products.length>0);
}
$$('[data-biz-tab]').forEach(b=>b.addEventListener('click',()=>bizSetTab(b.dataset.bizTab)));
$('#bizType').addEventListener('change',bizUpdatePlan);
$('#bizShopSearch').addEventListener('input',bizRenderShop);
$('#bizRegisterBtn').addEventListener('click',()=>{
 const type=BIZ_TYPES[Number($('#bizType').value)||0],name=$('#bizName').value.trim(),owner=$('#bizOwner').value.trim(),phone=$('#bizPhone').value.trim(),description=$('#bizDescription').value.trim();
 if(!name||!owner||!phone)return toast('Enter business name, owner name and contact phone.');
 if(!$('#bizTerms').checked)return toast('Please confirm the demo trial terms.');
 const now=Date.now(),item={id:'BIZ-'+now.toString(36).toUpperCase(),type:type.name,price:type.price,name,owner,phone,description,startedAt:now};
 bizData.businesses.unshift(item);bizSave();bizRenderRegistered();
 $('#bizMessage').innerHTML='<div class="notice ok">Registration saved. Your 7-day free demo trial has started. After day 7, the listed monthly subscription would be due, but this prototype cannot collect payments or automatically restrict access.</div>';
 ['bizName','bizOwner','bizPhone','bizDescription'].forEach(id=>$('#'+id).value='');$('#bizTerms').checked=false;
 toast('Business registered with a 7-day demo trial.');bizSetTab('dashboard');
});
bizLoad();bizRenderTypes();bizRenderRegistered();

